{"content":"/* Minimal libc for MIPS VM (x86 syscall numbers via syscall insn) */
#include <stddef.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ---- raw syscalls (VM uses x86 numbers) ---- */
static int raw_sys(int n, int a, int b, int c) {
    register int r2 __asm__("$2") = n;
    register int r4 __asm__("$4") = a;
    register int r5 __asm__("$5") = b;
    register int r6 __asm__("$6") = c;
    __asm__ volatile("syscall" : "+r"(r2) : "r"(r4), "r"(r5), "r"(r6) : "memory");
    return r2;
}
#define SYS_READ 0
#define SYS_WRITE 1
#define SYS_OPEN 2
#define SYS_CLOSE 3
#define SYS_LSEEK 8
#define SYS_TIME 201

int errno;

static int sys_read(int fd, void *buf, int n){ return raw_sys(SYS_READ, fd, (int)buf, n); }
static int sys_write(int fd, const void *buf, int n){ return raw_sys(SYS_WRITE, fd, (int)buf, n); }
static int sys_open(const char *p, int f, int m){ return raw_sys(SYS_OPEN, (int)p, f, m); }
static int sys_close(int fd){ return raw_sys(SYS_CLOSE, fd, 0, 0); }
static int sys_lseek(int fd, int off, int w){ return raw_sys(SYS_LSEEK, fd, off, w); }

/* ---- ctype ---- */
int isalpha(int c){ return (c>='A'&&c<='Z')||(c>='a'&&c<='z'); }
int isdigit(int c){ return c>='0'&&c<='9'; }
int isalnum(int c){ return isalpha(c)||isdigit(c); }
int isspace(int c){ return c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\f'||c=='\v'; }
int isupper(int c){ return c>='A'&&c<='Z'; }
int islower(int c){ return c>='a'&&c<='z'; }
int isxdigit(int c){ return isdigit(c)||(c>='a'&&c<='f')||(c>='A'&&c<='F'); }
int toupper(int c){ return (c>='a'&&c<='z')?c-32:c; }
int tolower(int c){ return (c>='A'&&c<='Z')?c+32:c; }

/* ---- string ---- */
void *memcpy(void *d, const void *s, size_t n){
    unsigned char *dd=d; const unsigned char *ss=s;
    while(n--) *dd++=*ss++;
    return d;
}
void *memmove(void *d, const void *s, size_t n){
    unsigned char *dd=d; const unsigned char *ss=s;
    if(dd<ss){ while(n--) *dd++=*ss++; }
    else if(dd>ss){ dd+=n; ss+=n; while(n--) *--dd=*--ss; }
    return d;
}
void *memset(void *s, int c, size_t n){
    unsigned char *p=s;
    while(n--) *p++=(unsigned char)c;
    return s;
}
int memcmp(const void *a, const void *b, size_t n){
    const unsigned char *p=a,*q=b;
    while(n--){ if(*p!=*q) return *p-*q; p++; q++; }
    return 0;
}
void *memchr(const void *s, int c, size_t n){
    const unsigned char *p=s;
    while(n--){ if(*p==(unsigned char)c) return (void*)p; p++; }
    return 0;
}
size_t strlen(const char *s){ size_t n=0; while(s[n]) n++; return n; }
char *strcpy(char *d, const char *s){ char *r=d; while((*d++=*s++)); return r; }
char *strncpy(char *d, const char *s, size_t n){
    size_t i=0; for(;i<n&&s[i];i++) d[i]=s[i];
    for(;i<n;i++) d[i]='\0';
    return d;
}
char *strcat(char *d, const char *s){ strcpy(d+strlen(d),s); return d; }
char *strncat(char *d, const char *s, size_t n){
    size_t dl=strlen(d); size_t i=0;
    for(;i<n&&s[i];i++) d[dl+i]=s[i];
    d[dl+i]='\0'; return d;
}
int strcmp(const char *a, const char *b){
    while(*a&&*a==*b){a++;b++;}
    return (unsigned char)*a-(unsigned char)*b;
}
int strncmp(const char *a, const char *b, size_t n){
    while(n--){ if(*a!=*b) return (unsigned char)*a-(unsigned char)*b; if(!*a) return 0; a++;b++; }
    return 0;
}
char *strchr(const char *s, int c){
    while(*s){ if(*s==(char)c) return (char*)s; s++; }
    return (c==0)?(char*)s:0;
}
char *strrchr(const char *s, int c){
    const char *r=0;
    while(*s){ if(*s==(char)c) r=s; s++; }
    if(c==0) return (char*)s;
    return (char*)r;
}
char *strstr(const char *h, const char *n){
    if(!*n) return (char*)h;
    size_t nl=strlen(n);
    while(*h){ if(*h==*n&&strncmp(h,n,nl)==0) return (char*)h; h++; }
    return 0;
